/// System locale provider — reacts to device locale changes.
final systemLocaleProvider = Provider<Locale>((ref) {
  return PlatformDispatcher.instance.locale;
});

/// Central locale provider — switching this instantly re-builds MaterialApp.
final localeProvider = StateProvider<Locale>((ref) {
  final storage = ref.watch(storageServiceProvider);
  final code = storage.appLanguage;
  if (code == 'system') {
    return ref.watch(systemLocaleProvider);
  }
  return _localeFromCode(code);
});

Locale _localeFromCode(String code) {
  if (code.toLowerCase() == 'english') return const Locale('en');
  if (code.contains('_')) {
    final parts = code.split('_');
    return Locale(parts[0], parts.length > 1 ? parts[1] : null);
  }
  return Locale(code);
}

class AppLocalizations {
  final Locale locale;

  AppLocalizations(this.locale);

  static const LocalizationsDelegate<AppLocalizations> delegate =
      _AppLocalizationsDelegate();

  static AppLocalizations of(BuildContext context) =>
      Localizations.of<AppLocalizations>(context, AppLocalizations)!;

  String _t(String key, [Map<String, String>? args]) {
    final table = _translations[locale.languageCode] ?? _translations['en']!;
    var value = table[key] ?? _translations['en']![key] ?? key;
    if (args != null) {
      for (final e in args.entries) {
        value = value.replaceAll('{${e.key}}', e.value);
      }
    }
    return value;
  }

