  /// Localized month name (1–12); falls back to English.
  String monthName(int month) {
    if (month < 1 || month > 12) return '';
    return _t('month$month');
  }

  /// Localized period caption for discovery shelves (UTC windows + months).
  String periodLabelFor(String periodId, {int? month, int? year}) {
    switch (periodId) {
      case 'last7Days':
        return periodLast7Days;
      case 'last30Days':
        return periodLast30Days;
      case 'currentMonth':
      case 'previousMonth':
        if (month == null || year == null) return '';
        return '${monthName(month)} $year';
      default:
        return '';
    }
  }

