/// Weekday names (Monday→Sunday) per supported language, used by
/// `recommendedForYou()` so the "Recommended for you this {day}" title is
/// written in the SELECTED app language. Missing languages use English, the
/// same fallback the whole app already uses.
const Map<String, List<String>> _weekdayNames = {
  'en': ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'],
  'fo': ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'],
  'fr': ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'],
  'es': ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'],
